// TestHasBMI2AndADX checks the CPUID test of the assembly against the CPU
// flags that Linux reports, so that a wrong test cannot silently disable
// the assembly.
func TestHasBMI2AndADX(t *testing.T) {
	t.Parallel()

	cpuinfo, err := os.ReadFile("/proc/cpuinfo")
	if err != nil {
		t.Skipf("reading the CPU flags: %v", err)
	}

	for line := range strings.Lines(string(cpuinfo)) {
		name, value, ok := strings.Cut(line, ":")
		if !ok || strings.TrimSpace(name) != "flags" {
			continue
		}

		flags := strings.Fields(value)
		want := slices.Contains(flags, "bmi2") && slices.Contains(flags, "adx")

		if got := hasBMI2AndADX(); got != want {
			t.Fatalf("hasBMI2AndADX() = %v, but /proc/cpuinfo has flags %q", got, flags)
		}

		return
	}

	t.Skip("/proc/cpuinfo has no CPU flags")
}

