// skipWithoutAsm skips a test of the assembly on a CPU that can't run it.
func skipWithoutAsm(t *testing.T) {
	t.Helper()

	if !hasBMI2AndADX() {
		t.Skip("the CPU lacks BMI2 or ADX")
	}
}

